 m.EDITION='current';m.STYLE='source';m.OUTPUT=OUT;m.BASE='https://www.3drotterdam.nl/datasource-data/25da2fa9-d5b7-4d44-b100-7ab3b3bf51dc/';OUT.mkdir(exist_ok=True)
 evidence=json.loads((SOURCE/'inspection.json').read_text());raw=gzip.decompress((SOURCE/'raw/16_67119_13875.b3dm.gz').read_bytes());assert m.digest(raw)==evidence['sourceSha256'];doc,binary,batch,feature=next(m.b3dm_parts(raw));glb,rtc,ids,images=m.convert(doc,binary,batch,feature,'',feature_kind='tanks');name='16-67119-13875-native.glb';stored=m.deployable(glb);(OUT/name).write_bytes(stored);_,nativeinfo=m.texture_lod(glb);leaves=[];entries=[]
